import java.nio.file.*;import org.objectweb.asm.*;
public class PatchTrap{public static void main(String[] a)throws Exception{var r=new ClassReader(Files.readAllBytes(Path.of(a[0])));var w=new ClassWriter(0);int[] n={0};r.accept(new ClassVisitor(Opcodes.ASM9,w){public MethodVisitor visitMethod(int acc,String name,String desc,String sig,String[] ex){var base=super.visitMethod(acc,name,desc,sig,ex);if(!name.equals("impact"))return base;return new MethodVisitor(Opcodes.ASM9,base){public void visitLdcInsn(Object value){if(value instanceof Float f&&f==.75f){value=.6f;n[0]++;}super.visitLdcInsn(value);}};}},0);if(n[0]!=1)throw new AssertionError("Expected one improved trap coefficient, got "+n[0]);Files.write(Path.of(a[1]),w.toByteArray());}}
